4	/*
5	 Implements a butterfly module for a FFT.
6	 
7	 Takes complex numbers W, XA, XB and returns
8	 YA = XA + W*XB
9	 YB = XA - W*XB
10	 
11	 It can take input no more frequently than once every
12	 two steps.  This is so, hopefully, less multiply
13	 blocks can be used.
14	 */
15	
16	module butterfly
17	  #(
18	    // The width of m_in.
19	    parameter M_WDTH = 0,
20	    // The width of the input, output and twiddle factors.
21	    parameter X_WDTH = 0
22	    )
23	   (
24	    input wire                        clk,
25	    input wire                        rst_n,
26	    // m_in contains data that passes through this block with no change.
27	    // It is delayed for 3 counts like x_nd->y_nd.
28	    input wire [M_WDTH-1:0]           m_in,
29	    // The twiddle factor.
30	    input wire signed [2*X_WDTH-1:0]  w,
31	    // XA
32	    input wire signed [2*X_WDTH-1:0]  xa,
33	    // XB
34	    input wire signed [2*X_WDTH-1:0]  xb,
35	    // Set to 1 when new data is present on inputs.
36	    // Cannot be set to 1 for two consecutive steps.
37	    input wire                        x_nd,
38	    // delayed version of m_in.
39	    output reg [M_WDTH-1:0]           m_out,
40	    // YA = XA + W*XB
41	    // YB = XA - W*XB
42	    // When y_nd=1 y_re and y_im are outputing YA.
43	    // The step after they are outputting YB.
44	    output wire signed [2*X_WDTH-1:0] y,
45	    output reg                        y_nd
46	    );
47	
48	   // Set wire to the real and imag parts for convenience.
49	   wire signed [X_WDTH-1:0]        w_re;
50	   wire signed [X_WDTH-1:0]        w_im;
51	   assign w_re = w[2*X_WDTH-1:X_WDTH];
52	   assign w_im = w[X_WDTH-1:0];
53	   wire signed [X_WDTH-1:0]        xa_re;
54	   wire signed [X_WDTH-1:0]        xa_im;
55	   assign xa_re = xa[2*X_WDTH-1:X_WDTH];
56	   assign xa_im = xa[X_WDTH-1:0];
57	   wire signed [X_WDTH-1:0]        xb_re;
58	   wire signed [X_WDTH-1:0]        xb_im;
59	   assign xb_re = xb[2*X_WDTH-1:X_WDTH];
60	   assign xb_im = xb[X_WDTH-1:0];
61	   reg signed [X_WDTH-1: 0]        y_re;
62	   reg signed [X_WDTH-1: 0]        y_im;
63	   assign y = {y_re, y_im};
64	   
65	   // Delayed m_in.
66	   reg signed [M_WDTH-1:0]         m[1:0];
67	   // Delayed XA
68	   reg signed [X_WDTH-1:0]         za_re[1:0];
69	   reg signed [X_WDTH-1:0]         za_im[1:0];
70	   // Delayed XB
71	   reg signed [X_WDTH-1:0]         zb_re;
72	   reg signed [X_WDTH-1:0]         zb_im;
73	   // Delayed W
74	   reg signed [X_WDTH-1:0]         ww_re;
75	   reg signed [X_WDTH-1:0]         ww_im;
76	   // Delayed x_nd
77	   reg signed                      x_nd_old[2:0];
78	   // Storage for output of multipliers
79	   reg signed [2*X_WDTH-1:0]         zbw_m1;
80	   reg signed [2*X_WDTH-1:0]         zbw_m2;
81	   // W * XB
82	   reg signed [X_WDTH-1:0]         zbw_re;
83	   wire signed [X_WDTH-1:0]        zbw_im;
84	   assign zbw_im = (zbw_m1 >>> (X_WDTH-2)) + (zbw_m2 >>> (X_WDTH-2));
85	   reg signed [X_WDTH-1:0]         zbw_im_old;
86	   // Wire of longer length for adding or substracting W*XB to XA.
87	   // If we don't create longer wires for them then we can lose the
88	   // high bit.  The contents of these wires are downshifted into a
89	   // normal size for use.
90	   wire signed [X_WDTH:0]            z1_re_big;
91	   wire signed [X_WDTH:0]            z1_im_big;
92	   assign z1_re_big = za_re[0] + zbw_re;
93	   assign z1_im_big = za_im[0] + zbw_im;
94	   wire signed [X_WDTH:0]            z2_re_big;
95	   wire signed [X_WDTH:0]            z2_im_big;
96	   assign z2_re_big = za_re[1] - zbw_re;
97	   assign z2_im_big = za_im[1] - zbw_im_old;
98	   
99	  always @ (posedge clk or negedge rst_n)
100	    begin
101	      if (!rst_n)
102	        begin
103	           y_nd <= 1'b0;
104	        end
105	      else
106	        begin
107	           // Set delay for x_nd_old and m.
108	           x_nd_old[0] <= x_nd;
109	           x_nd_old[1] <= x_nd_old[0];
110	           x_nd_old[2] <= x_nd_old[1];
111	           m[0] <= m_in;
112	           m[1] <= m[0];
113	           m_out <= m[1];
114	           // STAGE 1
115	           if (x_nd)
116	             begin
117	                za_re[0] <= xa_re;
118	                za_im[0] <= xa_im;
119	                ww_re <= w_re;
120	                ww_im <= w_im;
121	                zb_re <= xb_re;
122	                zb_im <= xb_im;
123	                // We perform two multiplications for calculate the real part
124	                // of W*XB.
125	                zbw_m1 <= xb_re*w_re;
126	                zbw_m2 <= xb_im*w_im;
127	                if (x_nd_old[0])
128	                  $display("ERROR: BF got new data two steps in a row.");
129	             end
130	           if (x_nd_old[0])
131	           // STAGE 2
132	             begin
133	                // Now start the multiplications for the imag part of W*WB.
134	                zbw_m1 <= zb_re*ww_im;
135	                zbw_m2 <= zb_im*ww_re;
136	                // Downshift the multiplied results into normal width and
137	                // substract them.
138	                // Overflow is not possible upon substraction since we
139	                // know that W and XB both have magnitude less than 1
140	                // so their multiple must also.
141	                zbw_re <= (zbw_m1 >>> (X_WDTH-2)) - (zbw_m2 >>> (X_WDTH-2));
142	             end
143	           // STAGE 3
144	           if (x_nd_old[1])
145	             begin
146	                // We only need to shift the required delayed data
147	                // with XA every two steps since new input cannot
148	                // arrive more frequently than that.
149	                // XA is needed by a wire calculating z2_re_big and ze_im_big
150	                // next step.
151	                za_re[1] <= za_re[0];
152	                za_im[1] <= za_im[0];
153	                // Output YA.
154	                y_nd <= 1'b1;
155	                y_re <= z1_re_big >>> 1;
156	                y_im <= z1_im_big >>> 1;
157	                zbw_im_old <= zbw_im;
158	             end
159	           // STAGE 4
160	           if (x_nd_old[2])
161	             begin
162	                // Output YB.
163	                y_nd <= 1'b0;
164	                y_re <= z2_re_big >>> 1;
165	                y_im <= z2_im_big >>> 1;
166	             end
167	        end
168	    end
169	
170	endmodule

